  "skill": "trace:trace"
}

{
  "command": "cd /tmp/review-eval/baseline-KtQctc/baseline-opus-5-5-pr30-2-3421fb; ls docs/adr; git log --oneline main..HEAD; git log --oneline -3 main; gh issue view 1 --comments; gh pr view 2; git diff main...HEAD --stat",
  "description": "Inspect ADRs, branch, issue and PR"
}

{
  "command": "cd /tmp/review-eval/baseline-KtQctc/baseline-opus-5-5-pr30-2-3421fb; echo ---range; git log --oneline main..HEAD; echo ---stat; git diff main...HEAD --stat; echo ---issue; gh issue view 1 --json title,body,comments,state; echo ---pr; gh pr view 2 --json title,body,baseRefName,headRefName,state,comments,reviews",
  "description": "Inspect branch range, issue and PR as JSON"
}

{
  "command": "cd /tmp/review-eval/baseline-KtQctc/baseline-opus-5-5-pr30-2-3421fb; cat GLOSSARY.md; for f in docs/adr/*.md; do echo \"=== $f\"; cat \"$f\"; done; ls docs docs/agents 2>/dev/null",
  "description": "Read glossary and all ADRs"
}

{
  "command": "cd /tmp/review-eval/baseline-KtQctc/baseline-opus-5-5-pr30-2-3421fb; git show --stat HEAD; git rev-parse main origin/main HEAD; ls -la .claude; cat .claude/settings.json .claude/trace.json 2>&1; git ls-files .claude; gh pr diff 2 | head -50",
  "description": "Inspect the implementation commit and .claude files"
}

{
  "command": "cd /tmp/review-eval/baseline-KtQctc/baseline-opus-5-5-pr30-2-3421fb; git ls-tree -r main --name-only | grep -v '^archive/' ; git show main:.claude/settings.json; git show main:.claude/trace.json; git diff main HEAD | wc -c; gh pr view 2 --json files,commits,mergeable; cat docs/agents/*.md",
  "description": "Confirm files on main and PR contents"
}

{
  "skill": "code-review",
  "args": "low 2"
}

{
  "command": "gh pr diff 2 2>/dev/null || git diff main...HEAD"
}

{
  "skill": "mattpocock-skills:code-review",
  "args": "since main (merge-base a3720e6). Originating issue: #1. Standards include GLOSSARY.md and the active ADRs in docs/adr/."
}

{
  "command": "cd /tmp/review-eval/baseline-KtQctc/baseline-opus-5-5-pr30-2-3421fb; git show --format='%H %s' --name-status a3720e6 -- .claude; node -e 'const s=require(\"./.claude/settings.json\");console.log(\"deny has archive rule:\",s.permissions.deny.includes(\"Read(./archive/**)\"));JSON.parse(require(\"fs\").readFileSync(\".claude/trace.json\",\"utf8\"));console.log(\"trace.json valid JSON\")'; cat package.json | head -20",
  "description": "Verify the issue's two requirements on the tree"
}

{
  "command": "cd /tmp/review-eval/baseline-KtQctc/baseline-opus-5-5-pr30-2-3421fb; git show --format='%H %s' --name-status a3720e6 -- .claude; jq -e '.permissions.deny | index(\"Read(./archive/**)\")' .claude/settings.json && echo deny-ok; jq -e . .claude/trace.json && echo trace-json-ok; jq .scripts package.json",
  "description": "Verify settings deny rule and trace.json with jq"
}

{
  "command": "cd /tmp/review-eval/baseline-KtQctc/baseline-opus-5-5-pr30-2-3421fb; ls node_modules >/dev/null 2>&1 && echo has-node_modules; npm test 2>&1 | tail -15",
  "description": "Run the test suite",
  "timeout": 300000
}

{
  "command": "cd /tmp/review-eval/baseline-KtQctc/baseline-opus-5-5-pr30-2-3421fb; npm test 2>&1 | grep -E '^# (tests|pass|fail)|^not ok|^  not ok|^    not ok' | head -30",
  "description": "Summarise test failures",
  "timeout": 300000
}

{
  "command": "cd /tmp/review-eval/baseline-KtQctc/baseline-opus-5-5-pr30-2-3421fb; npm test > $TMPDIR/t.log 2>&1; echo exit=$?; grep -nE '^ℹ (tests|pass|fail)|✖' $TMPDIR/t.log | head -30",
  "description": "Capture test log and list failures",
  "timeout": 300000
}

{
  "command": "cd /tmp/review-eval/baseline-KtQctc/baseline-opus-5-5-pr30-2-3421fb; sed -n 40,99p $TMPDIR/t.log; sed -n 109,160p $TMPDIR/t.log; git diff --quiet main HEAD && echo \"HEAD tree identical to main\"",
  "description": "Show failing test details"
}

{
  "skill": "mattpocock-skills:pr",
  "args": "PR #2 for issue #1 — the diff is empty (the branch has one empty commit; main already carries both requested changes)."
}

{
  "command": "cd /tmp/review-eval/baseline-KtQctc/baseline-opus-5-5-pr30-2-3421fb; gh pr edit --body-file $TMPDIR/prbody.md && gh pr view --json body --jq .body | tail -4",
  "description": "Update the PR body from the PR's branch"
}

{
  "command": "cd /tmp/review-eval/baseline-KtQctc/baseline-opus-5-5-pr30-2-3421fb; gh api repos/trace-eval-rocky/baseline-opus-5-5-pr30-2-3421fb/pulls/2 --jq .body | head -3",
  "description": "Check PR body via REST API"
}

{
  "command": "cd /tmp/review-eval/baseline-KtQctc/baseline-opus-5-5-pr30-2-3421fb; gh api --method PATCH repos/trace-eval-rocky/baseline-opus-5-5-pr30-2-3421fb/pulls/2 -F body=@$TMPDIR/prbody.md --jq '.body' | tail -3",
  "description": "Set PR body via REST API"
}

{
  "command": "cd /tmp/review-eval/baseline-KtQctc/baseline-opus-5-5-pr30-2-3421fb; gh api --method PATCH repos/trace-eval-rocky/baseline-opus-5-5-pr30-2-3421fb/pulls/2 -F body=@$TMPDIR/prbody.md --jq '.body' | sed -n '1p;$p'",
